#!/usr/bin/env python3
"""Reproducible, synthetic-only output diagnostics; preserves upstream notices.
Startup priming skips clock queries; real runtime timestamp failures stop this queue.
"""
from instrument_null_sink import ROOT,replace
if __name__=='__main__':
 replace(ROOT/"client/player/coreaudio_player.hpp",'    long lastChunkTick;','    long lastChunkTick=0;\n    uint64_t mb_callbacks_=0,mb_pulses_=0,mb_nonzero_=0,mb_quiet_=48000;\n    uint64_t mb_time_errors_=0,mb_enqueue_errors_=0,mb_overlimit_=0;\n    int mb_peak_=0;\n    bool mb_reported_=false,mb_priming_=true;\n    uint64_t mb_priming_time_errors_=0,mb_running_time_errors_=0;\n    int mb_last_time_status_=0;\n    uint64_t mb_priming_queries_skipped_=0;')
 replace(ROOT/"client/player/coreaudio_player.cpp",'    AudioTimeStamp timestamp;\n    AudioQueueGetCurrentTime(queue, timeLine_, &timestamp, NULL);\n','    ++mb_callbacks_;\n    AudioTimeStamp timestamp{};\n    if(mb_priming_) {\n        ++mb_priming_queries_skipped_; // No playback clock exists before start.\n    } else {\n        OSStatus mb_status=AudioQueueGetCurrentTime(queue,timeLine_,&timestamp,NULL);\n        if(mb_status!=noErr || !(timestamp.mFlags & kAudioTimeStampSampleTimeValid)) {\n            ++mb_time_errors_;++mb_running_time_errors_;mb_last_time_status_=mb_status;\n            memset(bufferRef->mAudioData,0,bufferRef->mAudioDataByteSize);\n            active_=false; // Fail closed on a real runtime timing error.\n            uninitAudioQueue(queue);\n            return;\n        }\n    }\n')
 replace(ROOT/"client/player/coreaudio_player.cpp",'    //    OSStatus status =\n    AudioQueueEnqueueBuffer(queue, bufferRef, 0, NULL);\n','    // Diagnostic safety ceiling: only this agreed low-amplitude synthetic test.\n    if(pubStream_->getFormat().bits()==16 && pubStream_->getFormat().channels()==2) {\n        for(size_t i=0;i<frames_;i++) {\n            int16_t values[2]; memcpy(values,buffer+i*4,4);\n            bool nonzero=false;\n            for(int c=0;c<2;c++) {\n                int magnitude=values[c]<0?-int(values[c]):int(values[c]);\n                if(magnitude>164) {values[c]=0;++mb_overlimit_;magnitude=0;}\n                if(magnitude>mb_peak_) mb_peak_=magnitude;\n                nonzero=nonzero || values[c]!=0;\n            }\n            memcpy(buffer+i*4,values,4);\n            if(nonzero) {if(mb_quiet_>=2400) ++mb_pulses_;mb_quiet_=0;++mb_nonzero_;}\n            else ++mb_quiet_;\n        }\n    } else memset(buffer,0,bufferRef->mAudioDataByteSize);\n    if(AudioQueueEnqueueBuffer(queue,bufferRef,0,NULL)!=noErr) ++mb_enqueue_errors_;\n')
 replace(ROOT/"client/player/coreaudio_player.cpp",'    AudioQueueRef queue;\n','    // Initialize the timeout reference before callbacks, not from indeterminate memory.\n    lastChunkTick=chronos::getTickCount();\n    AudioQueueRef queue;\n')
 replace(ROOT/"client/player/coreaudio_player.cpp",'    AudioQueueBufferRef buffers[NUM_BUFFERS];\n    for (int i = 0; i < NUM_BUFFERS; i++)\n    {\n        AudioQueueAllocateBuffer(queue, buff_size_, &buffers[i]);\n        buffers[i]->mAudioDataByteSize = buff_size_;\n        callback(this, queue, buffers[i]);\n    }\n\n','    mb_priming_=true;\n    AudioQueueBufferRef buffers[NUM_BUFFERS];\n    for (int i = 0; i < NUM_BUFFERS; i++)\n    {\n        AudioQueueAllocateBuffer(queue, buff_size_, &buffers[i]);\n        buffers[i]->mAudioDataByteSize = buff_size_;\n        callback(this, queue, buffers[i]);\n    }\n\n    mb_priming_=false;\n')
 replace(ROOT/"client/player/coreaudio_player.cpp",'    AudioQueueStop(queue, false);\n','    if(!mb_reported_) {\n        mb_reported_=true;\n        LOG(INFO,LOG_TAG) << "MACBEE_COREAUDIO {\\"callbacks\\":" << mb_callbacks_\n          << ",\\"pulses\\":" << mb_pulses_ << ",\\"nonzero_frames\\":" << mb_nonzero_\n          << ",\\"peak_int16\\":" << mb_peak_ << ",\\"time_errors\\":" << mb_time_errors_\n          << ",\\"priming_time_errors\\":" << mb_priming_time_errors_ << ",\\"running_time_errors\\":" << mb_running_time_errors_\n          << ",\\"priming_queries_skipped\\":" << mb_priming_queries_skipped_\n          << ",\\"last_time_status\\":" << mb_last_time_status_ << ",\\"enqueue_errors\\":" << mb_enqueue_errors_ << ",\\"overlimit_samples\\":" << mb_overlimit_ << "}\\n";\n    }\n    AudioQueueStop(queue, false);\n')
